// A round that reported nothing adds nothing, so a turn with no reported usage stays undefined.
export function addUsage(total: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (total === undefined) return next;
  if (next === undefined) return total;
  return {
    inputTokens: total.inputTokens + next.inputTokens,
    outputTokens: total.outputTokens + next.outputTokens,
    totalTokens: total.totalTokens + next.totalTokens,
  };
}
EOF
